function show(screen){el.setup.classList.toggle("hidden",screen!=="setup");el.auth.classList.toggle("hidden",screen!=="auth");el.app.classList.toggle("hidden",screen!=="app")}
function message(node,text="",error=false){node.textContent=text;node.classList.toggle("error",error)}
function escapeHtml(v=""){return String(v).replaceAll("&","&amp;").replaceAll("<","&lt;").replaceAll(">","&gt;").replaceAll('"',"&quot;").replaceAll("'","&#039;")}
function dateLabel(v,short=false){return new Intl.DateTimeFormat("ru-RU",short?{day:"2-digit",month:"short"}:{day:"2-digit",month:"short",year:"numeric"}).format(new Date(v))}
function imageFor(exercise){return exercise?.image_url||`./assets/exercises/${exercise?.image_slug||"leg-curl"}.png`}
function normalizeGroup(group){return ({Корпус:"Пресс",Трапеции:"Спина"})[group]||group}
function dayForGroup(group){return ["Ноги","Пресс"].includes(normalizeGroup(group))?"Ноги":"Спина"}
function imageSlugForGroup(group){return ({Ноги:"leg-press",Пресс:"ab-crunch",Спина:"seated-row",Грудь:"incline-dumbbell-press",Плечи:"smith-shoulder-press",Руки:"shrugs"})[normalizeGroup(group)]||"leg-curl"}
function muscleAsset(group){return ({Грудь:"chest",Пресс:"abs",Ноги:"legs",Спина:"back",Плечи:"shoulders",Руки:"arms"})[normalizeGroup(group)]||"back"}
function muscleBadge(group){const normalized=normalizeGroup(group);return `<span class="muscle-badge" aria-hidden="true"><img src="./assets/muscles/${muscleAsset(normalized)}.png" alt=""></span>`}
function resultLabel(set){const value=set.assistance_kg!=null?Number(set.assistance_kg):Number(set.weight_kg);return `${String(value).replace("-","−")} × ${set.reps}`}
function personSets(){return state.sets.filter(s=>s.athletes?.slug===state.athlete)}
function sortedHistory(exerciseId){return personSets().filter(s=>s.exercise_id===exerciseId).sort((a,b)=>new Date(a.workouts.performed_at)-new Date(b.workouts.performed_at))}
function latestByExercise(){const map=new Map();[...personSets()].sort((a,b)=>new Date(b.workouts.performed_at)-new Date(a.workouts.performed_at)).forEach(s=>{if(!map.has(s.exercise_id))map.set(s.exercise_id,s)});return [...map.values()]}
function showToast(text){el.toast.textContent=text;el.toast.classList.remove("hidden");setTimeout(()=>el.toast.classList.add("hidden"),2600)}
function applyAthleteTheme(){const isNatasha=state.athlete==="natasha";[el.app,document.body].forEach(node=>{node.classList.toggle("theme-natasha",isNatasha);node.classList.toggle("theme-artem",!isNatasha)});document.documentElement.style.colorScheme="light"}

async function ensureSeed(){
  if(state.athletes.length||!window.GYM_SEED)return;
  const aRes=await db.from("athletes").insert(window.GYM_SEED.athletes).select("id,slug,name"); if(aRes.error)throw aRes.error;
  const unique=new Map();window.GYM_SEED.records.forEach(r=>unique.set(r[4],{name:r[3],muscle_group:normalizeGroup(r[2]),image_slug:r[4]}));
  const eRes=await db.from("exercises").insert([...unique.values()]).select("id,name,muscle_group,image_slug,image_url");if(eRes.error)throw eRes.error;
  const dayRows=eRes.data.map((exercise,position)=>({exercise_id:exercise.id,day_type:dayForGroup(exercise.muscle_group),position}));const dRes=await db.from("workout_day_exercises").insert(dayRows);if(dRes.error)throw dRes.error;
  const athleteIds=Object.fromEntries(aRes.data.map(a=>[a.slug,a.id]));const exerciseIds=Object.fromEntries(eRes.data.map(e=>[e.image_slug,e.id]));
  for(const date of [...new Set(window.GYM_SEED.records.map(r=>r[0]))]){
    const records=window.GYM_SEED.records.filter(r=>r[0]===date);const dayType=date==="2026-08-24"?"Спина":"Ноги";
    const wRes=await db.from("workouts").insert({performed_at:`${date}T12:00:00+02:00`,day_type:dayType,notes:"Импортировано из тренировочной базы"}).select("id").single();if(wRes.error)throw wRes.error;
    const rows=records.map((r,i)=>({workout_id:wRes.data.id,athlete_id:athleteIds[r[1]],exercise_id:exerciseIds[r[4]],set_order:i+1,weight_kg:r[5]??0,assistance_kg:r[6],reps:r[7],is_warmup:false,next_step:r[9],comment:r[10]||null}));
    const sRes=await db.from("workout_sets").insert(rows);if(sRes.error)throw sRes.error;
  }
  state.seeded=true;
}

async function loadData(){
  const [a,e,s,d]=await Promise.all([
    db.from("athletes").select("id,slug,name").order("name"),
    db.from("exercises").select("id,name,muscle_group,image_slug,image_url").order("name"),
    db.from("workout_sets").select("id,workout_id,athlete_id,exercise_id,set_order,weight_kg,assistance_kg,reps,next_step,comment,workouts(id,performed_at,day_type),athletes(id,slug,name),exercises(id,name,muscle_group,image_slug,image_url)"),
    db.from("workout_day_exercises").select("exercise_id,day_type,position").order("position")
  ]);if(a.error)throw a.error;if(e.error)throw e.error;if(s.error)throw s.error;if(d.error)throw d.error;
  state.athletes=a.data??[];state.exercises=(e.data??[]).map(exercise=>({...exercise,muscle_group:normalizeGroup(exercise.muscle_group)}));state.sets=(s.data??[]).filter(x=>x.athletes&&x.exercises&&x.workouts).map(set=>({...set,exercises:{...set.exercises,muscle_group:normalizeGroup(set.exercises.muscle_group)}}));state.dayExercises=d.data??[];
  if(!state.athletes.length){await ensureSeed();return loadData()}
  state.athlete=state.athlete&&state.athletes.some(a=>a.slug===state.athlete)?state.athlete:(state.athletes.find(a=>a.slug==="artem")?.slug||state.athletes[0].slug);
  if(!state.exerciseId)state.exerciseId=latestByExercise()[0]?.exercise_id||null;render();
}

function renderAthletes(){applyAthleteTheme();const html=state.athletes.map(a=>`<button class="${a.slug===state.athlete?"active":""}" data-athlete="${a.slug}" type="button">${escapeHtml(a.name)}</button>`).join("");el.athletes.innerHTML=html;el.recordAthletes.innerHTML=state.athletes.map(a=>`<button class="${a.slug===state.recordAthlete?"active":""}" data-record-athlete="${a.slug}" type="button">${escapeHtml(a.name)}</button>`).join("");$$('[data-athlete]').forEach(b=>b.onclick=()=>{state.athlete=b.dataset.athlete;state.exerciseId=latestByExercise()[0]?.exercise_id||null;render()});$$('[data-record-athlete]').forEach(b=>b.onclick=()=>{state.recordAthlete=b.dataset.recordAthlete;renderAthletes()})}
function changeLabel(history){if(history.length<2)return {text:"Первая запись",kind:"wait",icon:"horizontal_rule"};const prev=history.at(-2),last=history.at(-1);const prevLoad=prev.assistance_kg??prev.weight_kg,lastLoad=last.assistance_kg??last.weight_kg;if(Number(lastLoad)!==Number(prevLoad)){const delta=Number(lastLoad)-Number(prevLoad);return {text:`${delta>0?"+":""}${String(delta).replace("-","−")} кг`,kind:"good",icon:"trending_up"}}const delta=last.reps-prev.reps;return delta>0?{text:`+${delta} повт.`,kind:"good",icon:"trending_up"}:{text:"Без изменений",kind:"wait",icon:"trending_flat"}}
function renderFilters(){const groups=[...new Set(state.exercises.map(e=>e.muscle_group).filter(Boolean))].sort();const current=el.group.value;el.group.innerHTML='<option value="all">Все группы</option>'+groups.map(g=>`<option value="${escapeHtml(g)}">${escapeHtml(g)}</option>`).join("");el.group.value=groups.includes(current)?current:"all"}
function renderList(){let rows=latestByExercise();const recorded=new Set(rows.map(row=>row.exercise_id));rows=[...state.exercises.filter(exercise=>!recorded.has(exercise.id)).map(exercise=>({exercise_id:exercise.id,exercises:exercise,unrecorded:true})),...rows];const q=el.search.value.trim().toLowerCase(),group=el.group.value;rows=rows.filter(s=>(group==="all"||s.exercises.muscle_group===group)&&(!q||s.exercises.name.toLowerCase().includes(q)));if(!rows.length){el.list.innerHTML='<div class="empty-list">Нет результатов по выбранному фильтру</div>';return}el.list.innerHTML=rows.map(s=>{const h=sortedHistory(s.exercise_id),delta=s.unrecorded?{kind:"",icon:"add_circle",text:"Записать подход"}:changeLabel(h),groupName=s.exercises.muscle_group||"";return `<button class="result-row ${s.exercise_id===state.exerciseId?"selected":""}" data-exercise="${s.exercise_id}" type="button"><span class="exercise-cell"><img src="${imageFor(s.exercises)}" alt="${escapeHtml(s.exercises.name)}"><span class="exercise-copy"><span class="exercise-name-line">${muscleBadge(groupName)}<strong>${escapeHtml(s.exercises.name)}</strong></span><small>${escapeHtml(groupName)}</small></span></span><span class="primary-result">${s.unrecorded?"Нет записей":resultLabel(s)}</span><span>${s.unrecorded?"—":dateLabel(s.workouts.performed_at,true)}</span><span class="target">${s.unrecorded?"Запишите первый результат":escapeHtml(s.next_step||"Повторить результат")}</span><span class="delta ${delta.kind}"><span class="material-symbols-rounded">${delta.icon}</span>${delta.text}</span></button>`}).join("");$$('[data-exercise]').forEach(b=>b.onclick=()=>{state.exerciseId=b.dataset.exercise;if(!latestFor(state.exerciseId)){closeDetail();openDrawer();state.recordDay=state.dayExercises.find(row=>row.exercise_id===state.exerciseId)?.day_type||dayForGroup(currentExercise().muscle_group);selectRecordExercise(state.exerciseId);return}renderList();renderDetail();if(matchMedia("(max-width: 980px)").matches){el.app.classList.add("detail-open");$("#detail-pane").classList.add("mobile-open");document.body.style.overflow="hidden"}})}
function closeDetail(){$("#detail-pane").classList.remove("mobile-open");el.app.classList.remove("detail-open");document.body.style.overflow=""}
function estimatedMax(set){return Number(set.weight_kg||0)*(1+Number(set.reps||0)/30)}
function bestSessionPoints(history,assisted){const sessions=new Map();history.forEach(set=>{const key=set.workout_id||set.workouts.id,current=sessions.get(key),rank=assisted?Number(set.assistance_kg??-9999)*1000+Number(set.reps):estimatedMax(set);if(!current||rank>current.rank)sessions.set(key,{set,rank})});return [...sessions.values()].map(x=>x.set).sort((a,b)=>new Date(a.workouts.performed_at)-new Date(b.workouts.performed_at))}
function progressPercent(points,assisted){if(points.length<2)return 0;const first=points[0],last=points.at(-1);if(assisted){const firstLoad=Number(first.assistance_kg??0),lastLoad=Number(last.assistance_kg??0);if(firstLoad!==lastLoad)return Math.round((lastLoad-firstLoad)/Math.max(1,Math.abs(firstLoad))*100);return Math.round((Number(last.reps)-Number(first.reps))/Math.max(1,Number(first.reps))*100)}const firstMax=estimatedMax(first),lastMax=estimatedMax(last);return firstMax?Math.round((lastMax-firstMax)/firstMax*100):0}
function destroyCharts(){state.charts.forEach(chart=>chart.destroy());state.charts=[]}
