function makeLoadRepsChart(canvas,labels,loads,reps,loadColor){const single=labels.length===1;return new Chart(canvas,{type:"line",data:{labels,datasets:[{label:"Вес, кг",data:loads.map(Number),yAxisID:"yLoad",borderColor:loadColor,backgroundColor:`${loadColor}18`,fill:true,tension:.28,pointRadius:single?5:3.5,pointHoverRadius:6,borderWidth:2.5},{label:"Повторения",data:reps.map(Number),yAxisID:"yReps",borderColor:"#27864b",backgroundColor:"#27864b18",fill:false,tension:.28,pointRadius:single?5:3.5,pointHoverRadius:6,borderWidth:2.5}]},options:{responsive:true,maintainAspectRatio:false,interaction:{intersect:false,mode:"index"},plugins:{legend:{display:true,position:"top",align:"start",labels:{usePointStyle:true,boxWidth:8,boxHeight:8,font:{family:"Manrope",size:10}}},tooltip:{callbacks:{label:ctx=>`${ctx.dataset.label}: ${ctx.parsed.y}${ctx.dataset.yAxisID==="yLoad"?" кг":" повт."}`}}},scales:{x:{grid:{display:false},ticks:{font:{family:"Manrope",size:10},maxRotation:0,autoSkip:true,maxTicksLimit:5}},yLoad:{position:"left",grace:"15%",grid:{color:"#e5eaed"},ticks:{font:{family:"Manrope",size:10},maxTicksLimit:5},title:{display:true,text:"кг",font:{family:"Manrope",size:10}}},yReps:{position:"right",grace:"15%",grid:{drawOnChartArea:false},ticks:{font:{family:"Manrope",size:10},maxTicksLimit:5,precision:0},title:{display:true,text:"повт.",font:{family:"Manrope",size:10}}}}}})}
function renderDetail(){const history=sortedHistory(state.exerciseId);if(!history.length){el.detailEmpty.classList.remove("hidden");el.detail.classList.add("hidden");destroyCharts();return}el.detailEmpty.classList.add("hidden");el.detail.classList.remove("hidden");const latest=history.at(-1),exercise=latest.exercises,assisted=history.some(s=>s.assistance_kg!=null),points=bestSessionPoints(history,assisted),progress=progressPercent(points,assisted),loads=points.map(s=>Number(s.assistance_kg??s.weight_kg)),reps=points.map(s=>Number(s.reps)),maxes=points.map(estimatedMax),bestLoad=assisted?(loads.every(v=>v>=0)?Math.min(...loads):Math.max(...loads)):Math.max(...loads),bestIndex=assisted?loads.indexOf(bestLoad):maxes.indexOf(Math.max(...maxes)),bestSet=points[Math.max(0,bestIndex)];$("#detail-group").textContent=exercise.muscle_group||"Упражнение";$("#detail-muscle-icon").classList.remove("material-symbols-rounded");$("#detail-muscle-icon").innerHTML=`<img src="./assets/muscles/${muscleAsset(exercise.muscle_group)}.png" alt="">`;$("#detail-name").textContent=exercise.name;$("#detail-result").textContent=resultLabel(latest);$("#detail-date").textContent=dateLabel(latest.workouts.performed_at);$("#detail-target").textContent=latest.next_step||"Повторить результат";$("#detail-progress").textContent=`${progress>0?"+":""}${progress}%`;$("#detail-progress").className=progress>0?"positive":progress<0?"negative":"";$("#detail-sessions").textContent=`${points.length} ${points.length===1?"тренировка":"тренировок"}`;$("#best-load-label").textContent=assisted?"Минимальная помощь":"Лучший вес";$("#best-load").textContent=`${String(bestLoad).replace("-","−")} кг`;$("#best-reps").textContent=Math.max(...reps);$("#estimated-max-card").querySelector("span").textContent=assisted?"Лучший подход":"Расчётный 1ПМ";$("#estimated-max").textContent=assisted?resultLabel(bestSet):`${Math.round(Math.max(...maxes)*10)/10} кг`;$("#load-chart-title").textContent=assisted?"Помощь и повторения":"Рабочий вес и повторения";$("#strength-chart-card").classList.toggle("hidden",assisted);$("#history-list").innerHTML=[...history].reverse().map(s=>`<div class="history-row"><span>${dateLabel(s.workouts.performed_at,true)}</span><strong>${resultLabel(s)}</strong><small>${escapeHtml(s.comment||s.next_step||"")}</small></div>`).join("");destroyCharts();const labels=points.map(s=>dateLabel(s.workouts.performed_at,true)),primary=getComputedStyle(el.app).getPropertyValue("--theme-accent").trim()||"#2e6687";state.charts.push(makeLoadRepsChart($("#load-chart"),labels,loads,reps,primary));if(!assisted)state.charts.push(makeTrendChart($("#strength-chart"),labels,maxes,"#6f61a8"," кг"))}
