function setDrawerStep(step){["day","exercise","values"].forEach(x=>$("#record-step-"+x).classList.toggle("hidden",x!==step));const i={day:0,exercise:1,values:2}[step];$$('.drawer-progress span').forEach((s,n)=>s.classList.toggle("active",n<=i));$("#record-title").textContent=step==="day"?"Выберите день":step==="exercise"?`День: ${state.recordDay}`:"Запишите результат"}
function openDrawer(){state.recordDay=null;state.recordExercise=null;state.recordAthlete=state.athlete;el.drawer.classList.add("open");el.drawer.setAttribute("aria-hidden","false");el.backdrop.classList.remove("hidden");document.body.style.overflow="hidden";setDrawerStep("day");renderAthletes()}
function closeDrawer(){el.drawer.classList.remove("open");el.drawer.setAttribute("aria-hidden","true");el.backdrop.classList.add("hidden");document.body.style.overflow=""}
function planExercises(day){const configuredIds=state.dayExercises.filter(row=>row.day_type===day).sort((a,b)=>(a.position??0)-(b.position??0)).map(row=>row.exercise_id);return configuredIds.map(id=>state.exercises.find(exercise=>exercise.id===id)).filter(Boolean)}
function captureDayDraft(){if(!state.dayDraft)return;state.dayDraft[state.settingsDay]=new Set($$("[data-day-exercise]:checked").map(input=>input.value))}
function renderDaySettings(){const selected=state.dayDraft?.[state.settingsDay]||new Set();$$('[data-settings-day]').forEach(button=>button.classList.toggle("active",button.dataset.settingsDay===state.settingsDay));el.daySettingsList.innerHTML=state.exercises.map(exercise=>`<label class="day-exercise-option"><input type="checkbox" data-day-exercise value="${exercise.id}" ${selected.has(exercise.id)?"checked":""}><span class="day-exercise-check material-symbols-rounded">check</span>${muscleBadge(exercise.muscle_group)}<span><strong>${escapeHtml(exercise.name)}</strong><small>${escapeHtml(exercise.muscle_group)}</small></span></label>`).join("")}
function openDaySettings(){state.settingsDay=state.recordDay||"Ноги";state.dayDraft={Ноги:new Set(planExercises("Ноги").map(exercise=>exercise.id)),Спина:new Set(planExercises("Спина").map(exercise=>exercise.id))};message(el.daySettingsMessage);renderDaySettings();el.daySettingsDialog.showModal()}
