async function loadNutrition(){if(!state.foods.length)state.foods=DEFAULT_FOODS.map(foodShape);const athlete=state.athletes.find(item=>item.slug===state.athlete);if(previewMode){if(!state.weights.length)state.weights=[{id:"w1",athlete_id:athlete?.id,recorded_on:"2026-08-27",weight_kg:84.2,note:"Первая запись"},{id:"w2",athlete_id:athlete?.id,recorded_on:"2026-08-29",weight_kg:83.6,note:"Утром"},{id:"w3",athlete_id:athlete?.id,recorded_on:"2026-09-02",weight_kg:83.1,note:"После сна"}];renderMealHistory();renderWeight();return}const [foodsResult,mealsResult,weightsResult]=await Promise.all([db.from("foods").select("id,name,aliases,kcal_per_100g,protein_per_100g,fat_per_100g,carbs_per_100g,unit_grams,cooking_buffer_percent").order("name"),db.from("meal_summaries").select("*").eq("athlete_id",athlete.id).gte("eaten_at",new Date(new Date().setHours(0,0,0,0)).toISOString()).order("eaten_at",{ascending:false}),db.from("weight_entries").select("id,athlete_id,recorded_on,weight_kg,note").eq("athlete_id",athlete.id).order("recorded_on")]);if(!foodsResult.error&&foodsResult.data?.length){const merged=new Map(DEFAULT_FOODS.map(food=>[normalizeFoodText(food.name),foodShape(food)]));foodsResult.data.map(foodShape).forEach(food=>merged.set(normalizeFoodText(food.name),food));state.foods=[...merged.values()]}if(!mealsResult.error)state.meals=mealsResult.data||[];if(!weightsResult.error)state.weights=weightsResult.data||[];renderMealHistory();renderWeight()}
async function parseMeal(event){event.preventDefault();const text=$("#meal-text").value.trim(),button=$("#calculate-meal");if(!text)return;button.disabled=true;message(el.nutritionMessage,"Разбираю продукты и порции…");let parsed=[],aiUsed=false;try{if(!previewMode){const result=await db.functions.invoke("parse-meal",{body:{text}});if(!result.error&&Array.isArray(result.data?.items)&&result.data.items.length){parsed=result.data.items;aiUsed=true}}if(!parsed.length)parsed=parseMealLocally(text);state.mealDraft=calculateMealItems(parsed);renderMealPreview();const unknown=state.mealDraft.filter(item=>item.unresolved).length;message(el.nutritionMessage,unknown?`Не удалось найти продуктов: ${unknown}. Уточните название или удалите строку.`:aiUsed?"Распознано нейросетью. Проверьте состав перед сохранением.":"Использован встроенный справочник. Проверьте состав перед сохранением.",Boolean(unknown));el.mealPreview.scrollIntoView({behavior:"smooth",block:"nearest"})}catch(error){message(el.nutritionMessage,error.message,true)}finally{button.disabled=false}}
async function saveMeal(){const button=$("#save-meal"),athlete=state.athletes.find(item=>item.slug===state.athlete),totals=nutritionTotals(state.mealDraft),name=$("#meal-name").value.trim()||"Приём пищи",eatenAt=new Date().toISOString();if(!state.mealDraft.length||state.mealDraft.some(item=>item.unresolved))return;button.disabled=true;message(el.nutritionMessage,"Сохраняю…");try{let meal={id:`preview-${Date.now()}`,athlete_id:athlete.id,name,eaten_at:eatenAt,total_kcal:totals.kcal,total_protein:totals.protein,total_fat:totals.fat,total_carbs:totals.carbs,macros_complete:totals.macrosComplete};if(!previewMode){const result=await db.from("meals").insert({athlete_id:athlete.id,name,eaten_at:eatenAt,source_text:$("#meal-text").value.trim()}).select("id,athlete_id,name,eaten_at").single();if(result.error)throw result.error;const rows=state.mealDraft.map((item,position)=>({meal_id:result.data.id,food_id:databaseFoodId(item.id),position,food_name:item.name,grams:item.grams,kcal_per_100g:item.kcal,protein_per_100g:item.protein,fat_per_100g:item.fat,carbs_per_100g:item.carbs,macros_known:item.macrosKnown!==false,cooking_buffer_percent:item.bufferPercent||0}));const itemsResult=await db.from("meal_items").insert(rows);if(itemsResult.error)throw itemsResult.error;meal={...meal,...result.data}}state.meals.unshift(meal);state.mealDraft=[];el.nutritionForm.reset();$("#meal-name").value="";renderMealPreview();renderMealHistory();message(el.nutritionMessage);showToast(`${name}: ${Math.round(totals.kcal)} ккал сохранено`)}catch(error){message(el.nutritionMessage,error.message,true)}finally{button.disabled=false}}
async function saveWeight(event){event.preventDefault();const button=$("#save-weight"),athlete=state.athletes.find(item=>item.slug===state.athlete),entry={athlete_id:athlete.id,recorded_on:$("#weight-date").value,weight_kg:Number($("#weight-value").value),note:$("#weight-note").value.trim()||null};button.disabled=true;message(el.weightMessage,"Сохраняю…");try{let saved={...entry,id:`preview-weight-${Date.now()}`};if(!previewMode){const result=await db.from("weight_entries").upsert(entry,{onConflict:"athlete_id,recorded_on"}).select("id,athlete_id,recorded_on,weight_kg,note").single();if(result.error)throw result.error;saved=result.data}state.weights=state.weights.filter(item=>!(item.athlete_id===athlete.id&&item.recorded_on===entry.recorded_on));state.weights.push(saved);$("#weight-value").value="";$("#weight-note").value="";message(el.weightMessage);renderWeight();showToast(`Вес ${formatMacro(entry.weight_kg)} кг сохранён`)}catch(error){message(el.weightMessage,error.message,true)}finally{button.disabled=false}}
