function bind(){
  $("#today-label").textContent=new Intl.DateTimeFormat("ru-RU",{day:"numeric",month:"long",year:"numeric"}).format(new Date());
  el.authForm.onsubmit=async e=>{e.preventDefault();const b=e.currentTarget.querySelector("button");b.disabled=true;const {error}=await db.auth.signInWithOtp({email:$("#email").value,options:{emailRedirectTo:`${location.origin}${location.pathname}`}});b.disabled=false;message(el.authMessage,error?error.message:"Ссылка отправлена. Проверьте почту.",Boolean(error))};
  $("#sign-out-button").onclick=()=>db.auth.signOut();$("#training-nav").onclick=()=>switchSection("training");$("#nutrition-nav").onclick=()=>switchSection("nutrition");$("#food-tab").onclick=()=>switchNutritionTab("food");$("#weight-tab").onclick=()=>switchNutritionTab("weight");el.nutritionForm.onsubmit=parseMeal;el.weightForm.onsubmit=saveWeight;$("#weight-date").value=new Date().toISOString().slice(0,10);$("#save-meal").onclick=saveMeal;$("#edit-meal").onclick=()=>{$("#meal-text").focus();$("#nutrition-form").scrollIntoView({behavior:"smooth"})};$$('[data-meal-example]').forEach(button=>button.onclick=()=>{$("#meal-text").value=button.dataset.mealExample;$("#meal-text").focus()});el.group.onchange=renderList;el.search.oninput=renderList;$("#open-recorder").onclick=openDrawer;$("#close-recorder").onclick=closeDrawer;$("#close-detail").onclick=closeDetail;el.backdrop.onclick=closeDrawer;$("#open-exercise-dialog").onclick=openExerciseDialog;$("#close-exercise-dialog").onclick=closeExerciseDialog;el.exerciseForm.onsubmit=saveExercise;$("#change-exercise-image").onclick=openImageDialog;$("#close-image-dialog").onclick=closeImageDialog;$("#exercise-image-file").onchange=previewExerciseImage;$("#reset-exercise-image").onclick=resetExerciseImage;el.imageForm.onsubmit=saveExerciseImage;$("#open-day-settings").onclick=openDaySettings;$("#close-day-settings").onclick=closeDaySettings;el.daySettingsForm.onsubmit=saveDaySettings;$$('[data-settings-day]').forEach(button=>button.onclick=()=>{captureDayDraft();state.settingsDay=button.dataset.settingsDay;renderDaySettings()});
  $$('.day-card').forEach(b=>b.onclick=()=>{state.recordDay=b.dataset.day;renderRecordExercises();setDrawerStep("exercise")});$("#back-to-day").onclick=()=>setDrawerStep("day");$("#back-to-exercises").onclick=()=>setDrawerStep("exercise");
  $$('.stepper button').forEach(b=>b.onclick=()=>{const input=b.dataset.step==="weight"?$("#record-weight"):$("#record-reps");input.value=Math.max(Number(input.min),Number(input.value||0)+Number(b.dataset.delta))});$("#record-form").onsubmit=saveRecord;
  document.addEventListener("keydown",e=>{if(e.key==="Escape"&&!el.exerciseDialog.open&&!el.imageDialog.open&&!el.daySettingsDialog.open)closeDrawer()});
}
async function sessionChanged(session){if(!session){show("auth");return}show("app");try{await loadData()}catch(error){console.error(error);showToast(`Ошибка базы: ${error.message}`)}}
